mapper.sql:
WHERE status = 'APPROVED'

    AND (title ILIKE '%' || #{q.keyword} || '%'
         OR doi ILIKE '%' || #{q.keyword} || '%'
         OR patent_no ILIKE '%' || #{q.keyword} || '%')


    AND output_type = #{q.outputType}


    AND dept_id = #{q.deptId}


    AND EXTRACT(YEAR FROM completed_at) = #{q.year}

WHERE (owner_id = #{q.ownerId} OR status = 'APPROVED')

    AND (title ILIKE '%' || #{q.keyword} || '%'
         OR doi ILIKE '%' || #{q.keyword} || '%'
         OR patent_no ILIKE '%' || #{q.keyword} || '%')


    AND output_type = #{q.outputType}


    AND status = #{q.status}


    AND dept_id = #{q.deptId}


    AND EXTRACT(YEAR FROM completed_at) = #{q.year}

mapper.select:
SELECT output_type AS group_key, COUNT(DISTINCT id) AS output_count FROM research_output WHERE status = 'APPROVED'
AND dept_id = #{deptId}
AND EXTRACT(YEAR FROM completed_at) = #{year}
GROUP BY output_type ORDER BY output_count DESC, output_type

SELECT CAST(EXTRACT(YEAR FROM completed_at) AS varchar) AS group_key, COUNT(DISTINCT id) AS output_count FROM research_output WHERE status = 'APPROVED' AND completed_at IS NOT NULL
AND dept_id = #{deptId}
GROUP BY EXTRACT(YEAR FROM completed_at) ORDER BY group_key

SELECT dept_id AS group_key, COUNT(DISTINCT id) AS output_count FROM research_output WHERE status = 'APPROVED'
AND EXTRACT(YEAR FROM completed_at) = #{year}
GROUP BY dept_id ORDER BY output_count DESC, dept_id
